mapper.sql:
select inventory.id as inv_id, inventory.sku_id, inventory.warehouse_id, inventory.quantity, ifnull(inventory.locked_quantity, 0) as locked_quantity, (inventory.quantity - ifnull(inventory.locked_quantity, 0)) as available_quantity, inventory.stock_code, inventory.move_count, inventory.remark as inv_remark, sku.sku_name, sku.barcode, sku.length, sku.width, sku.height, sku.volume, sku.gross_weight, sku.net_weight, sku.cost_price, sku.selling_price as sku_selling_price, item.id as item_id, item.item_code, item.item_name, item.item_image, item.item_category, item.unit, item.item_level, item.item_brand, item.item_model, item.supplier_id, item.selling_price as item_selling_price, item.delivery_days, item.safety_stock, category.category_name, merchant.merchant_name as supplier_name, warehouse.warehouse_name from wms_inventory inventory inner join wms_item_sku sku on inventory.sku_id=sku.id inner join wms_item item on sku.item_id=item.id left join wms_item_category category on category.id = item.item_category left join wms_merchant merchant on merchant.id = item.supplier_id left join wms_warehouse warehouse on warehouse.id = inventory.warehouse_id
item.item_name like concat('%', #{bo.itemName}, '%')
and item.item_code like concat('%', #{bo.itemCode}, '%')
and sku.sku_name like concat('%', #{bo.skuName}, '%')
and sku.sku_code like concat('%', #{bo.skuCode}, '%')
and item.item_category=#{bo.itemCategory}
and item.unit=#{bo.unit}
and item.id=#{bo.itemId}
and item.supplier_id=#{bo.supplierId}
and item.item_level=#{bo.itemLevel}
and item.item_model like concat('%', #{bo.itemModel}, '%')
and inventory.stock_code like concat('%', #{bo.stockCode}, '%')
and inventory.warehouse_id=#{bo.warehouseId}
and inventory.warehouse_id in
#{scopeWarehouseId}
and inventory.quantity>=#{bo.minQuantity}
and inventory.move_count >= #{bo.minMoveCount}
and item.safety_stock is not null and item.safety_stock > 0 and inventory.quantity < item.safety_stock
